if (points.empty() || k == 0) {
        return {};
    }

    std::size_t const actualK = std::min(k, points.size());

    std::vector<std::pair<float_t, size_t>> distances;
    distances.reserve(points.size());

    for (std::size_t i = 0; i < points.size(); ++i) {
        auto const& pt = points[i];
        float_t const dx = pt.x - searchPoint.x;
        float_t const dy = pt.y - searchPoint.y;
        float_t const dz = pt.z - searchPoint.z;
        float_t const distSq = dx * dx + dy * dy + dz * dz;
        distances.emplace_back(distSq, i);
    }

    std::partial_sort(distances.begin(), distances.begin() + actualK, distances.end(),
        [](auto const& a, auto const& b) { return a.first < b.first; });

    std::vector<size_t> result;
    result.reserve(actualK);
    for (std::size_t i = 0; i < actualK; ++i) {
        result.push_back(distances[i].second);
    }

    return result;
